  try {
    const ledger = await loadLedger(spindle, scope, userId);
    send({ type: "scope_edits_pushed", scope, entries: entriesView(ledger) }, userId);
  } catch (err) {
    log("warn", `load_character_workshop ${scope.kind}:${scope.id} failed: ${err.message}`);
  }
